SELECT  FROM sys_student_import_execution
WHERE requester_id = #{requesterId}
AND status = #{status}
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT  FROM sys_student_import_execution
WHERE credential_status = 'AVAILABLE' AND credential_expires_at <= #{now}
ORDER BY credential_expires_at, id LIMIT #{limit}
